import androidx.compose.foundation.*
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.*
import androidx.compose.ui.res.stringResource

@Composable
fun ShareSheetScreen(navigate: (String) -> Unit) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState()),
    ) {
        Spacer(modifier = Modifier.weight(1f))
        // Sheet
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surfaceContainerLow)
                .padding(AppTheme.spacing.spacing16),
            verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing16),
        ) {
            // Share Content
            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing24),
            ) {
                // Track Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing16),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Artwork(image = painterResource(R.drawable.img_27_849))
                    TrackMetadata(
                        title = "كيفك ع فراقى",
                        subtitle = "محمد شاكر وفضل شاكر",
                        showSubtitleIcon = false,
                        modifier = Modifier.weight(1f),
                    )
                }
                // Share Targets
                Row(modifier = Modifier.fillMaxWidth()) {
                    // Copy link Target
                    Column(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing8),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        IconButton(style = IconButtonStyle.Tonal, icon = AppIcons.Upload)
                    }
                    // Messages Target
                    Column(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing8),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        IconButton(style = IconButtonStyle.Tonal, icon = AppIcons.Groups)
                    }
                    // WhatsApp Target
                    Column(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing8),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        IconButton(style = IconButtonStyle.Tonal, icon = AppIcons.Share)
                    }
                    // Instagram Stories Target
                    Column(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing8),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        IconButton(style = IconButtonStyle.Tonal, icon = AppIcons.AutoAwesome)
                    }
                    // More Target
                    Column(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing8),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        IconButton(style = IconButtonStyle.Tonal, icon = AppIcons.MoreVert)
                    }
                }
            }
            Divider(modifier = Modifier.fillMaxWidth())
            Button(
                style = ButtonStyle.Text,
                labelText = stringResource(R.string.cancel),
                showLeadingIcon = false,
                modifier = Modifier.fillMaxWidth(),
            )
        }
    }
}

